        return settlementCache.computeIfAbsent(pair + "@" + date, k -> {
            vendorCalls++;
            String line = client.rate(pair, date);
            if (FxqClient.isCarriedForward(line)) {
                // vendor holiday: value is the previous business day's; use settlement source 3
                vendorCalls++;
                line = client.rate(pair, date, 3);
            }
            return FxqClient.parse(line).rate();
        });
